CREATE OR REPLACE FUNCTION public.increment(table_name text, column_name text, row_id uuid, id_column text)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
  result INTEGER;
BEGIN
  EXECUTE format('UPDATE %I SET %I = %I + 1 WHERE %I = %L RETURNING %I', table_name, column_name, column_name, id_column, row_id, column_name)
  INTO STRICT result;
  RETURN result;
EXCEPTION WHEN NO_DATA_FOUND THEN
  EXECUTE format('INSERT INTO %I (%I, %I) VALUES (%L, 1)', table_name, id_column, column_name, row_id);
  RETURN 1;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.increment_hug_count()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  update article
  set like_count = like_count + 1 
  where id = new.article_id;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.increment_like_count()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE article
     SET like_count = like_count + 1
   WHERE id = NEW.article_id;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.increment_rant_views(rant integer)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  new_views BIGINT;
BEGIN
  INSERT INTO rant_views (rant_id, views)
  VALUES (rant, 1)
  ON CONFLICT (rant_id)
  DO UPDATE SET views = rant_views.views + 1
  RETURNING views INTO new_views;

  RETURN new_views;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.increment_share_count(rant_id integer)
 RETURNS bigint
 LANGUAGE sql
AS $function$
  UPDATE article
  SET share_count = share_count + 1
  WHERE id = rant_id
  RETURNING share_count;
$function$
;

