  create policy "Authenticated Insert for Articles"
  on "public"."article"
  as permissive
  for insert
  to authenticated
with check ((auth.uid() IS NOT NULL));



  create policy "Authenticated Update for Articles"
  on "public"."article"
  as permissive
  for update
  to authenticated
using ((auth.uid() IS NOT NULL))
with check ((auth.uid() IS NOT NULL));



  create policy "Delete the article row"
  on "public"."article"
  as permissive
  for delete
  to public
using (true);



  create policy "Enable read access for all users"
  on "public"."article"
  as permissive
  for select
  to public
using (true);



  create policy "allow trigger updates"
  on "public"."article"
  as permissive
  for update
  to public
using (true);



