CREATE TRIGGER article_like_delete AFTER DELETE ON public.article_likes FOR EACH ROW EXECUTE FUNCTION public.decrement_like_count();

CREATE TRIGGER article_like_insert AFTER INSERT ON public.article_likes FOR EACH ROW EXECUTE FUNCTION public.increment_like_count();

CREATE TRIGGER trig_hug_count AFTER INSERT ON public.article_likes FOR EACH ROW EXECUTE FUNCTION public.increment_hug_count();


